WITH products_by_supplier AS (SELECT supplier_id, SUM(stock_qty) AS total_stock_qty, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(brand))) AS brand_values FROM products GROUP BY supplier_id) SELECT s.id, s.country, s.city, pbs.total_stock_qty, pbs.brand_values FROM suppliers s INNER JOIN products_by_supplier pbs ON s.id = pbs.supplier_id;
